CREATE TABLE #actual
(
    table_name  nvarchar(128) NOT NULL,
    column_name nvarchar(128) NOT NULL,
    type_name   nvarchar(40)  NOT NULL,
    is_nullable bit           NOT NULL,
    is_identity bit           NOT NULL
);

INSERT INTO #actual (table_name, column_name, type_name, is_nullable, is_identity)
SELECT s.name + N''.'' + o.name,
       c.name,
       CASE WHEN t.name IN (N''nvarchar'', N''nchar'') THEN t.name + N''('' + CASE WHEN c.max_length = -1 THEN N''max'' ELSE CAST(c.max_length / 2 AS nvarchar(10)) END + N'')''
            WHEN t.name IN (N''varchar'', N''char'', N''varbinary'', N''binary'') THEN t.name + N''('' + CASE WHEN c.max_length = -1 THEN N''max'' ELSE CAST(c.max_length AS nvarchar(10)) END + N'')''
            WHEN t.name IN (N''decimal'', N''numeric'') THEN t.name + N''('' + CAST(c.precision AS nvarchar(10)) + N'','' + CAST(c.scale AS nvarchar(10)) + N'')''
            WHEN t.name IN (N''datetime2'', N''time'', N''datetimeoffset'') THEN t.name + N''('' + CAST(c.scale AS nvarchar(10)) + N'')''
            WHEN t.name = N''timestamp'' THEN N''rowversion''
            ELSE t.name END,
       c.is_nullable,
       c.is_identity
FROM sys.columns c
JOIN sys.objects o ON o.object_id = c.object_id AND o.type = N''U''
JOIN sys.schemas s ON s.schema_id = o.schema_id AND s.name = N''app''
JOIN sys.types t ON t.user_type_id = c.user_type_id;

DECLARE @table nvarchar(128), @detail nvarchar(2000), @mismatch int;

DECLARE table_cursor CURSOR LOCAL FAST_FORWARD FOR
    SELECT DISTINCT table_name FROM #expected ORDER BY table_name;
OPEN table_cursor;
FETCH NEXT FROM table_cursor INTO @table;
WHILE @@FETCH_STATUS = 0
BEGIN
    SET @tables += 1;
    SET @mismatch = 0;

    IF OBJECT_ID(@table, N''U'') IS NULL
    BEGIN
        PRINT ''FAIL t_app_schema '' + @table + '' does not exist (run the migrations first)'';
        SET @failed += 1;
    END
    ELSE
    BEGIN
        IF OBJECTPROPERTY(OBJECT_ID(@table), N''TableHasPrimaryKey'') <> 1
        BEGIN
            PRINT ''FAIL t_app_schema '' + @table + '' has no primary key (the connector needs a declared key)'';
            SET @mismatch += 1;
        END

        -- missing or different columns
        DECLARE @col nvarchar(128), @want nvarchar(40), @got nvarchar(40), @wn bit, @gn bit, @wi bit, @gi bit, @have bit;
        DECLARE col_cursor CURSOR LOCAL FAST_FORWARD FOR
            SELECT e.column_name, e.type_name, e.is_nullable, e.is_identity,
                   a.type_name, a.is_nullable, a.is_identity,
                   CASE WHEN a.column_name IS NULL THEN 0 ELSE 1 END
            FROM #expected e
            LEFT JOIN #actual a ON a.table_name = e.table_name AND a.column_name = e.column_name
            WHERE e.table_name = @table
            ORDER BY e.ordinal;
        OPEN col_cursor;
        FETCH NEXT FROM col_cursor INTO @col, @want, @wn, @wi, @got, @gn, @gi, @have;
        WHILE @@FETCH_STATUS = 0
        BEGIN
            IF @have = 0
            BEGIN
                PRINT ''FAIL t_app_schema '' + @table + ''.'' + @col + '' is missing (dictionary: '' + @want + '')'';
                SET @mismatch += 1;
            END
            ELSE
            BEGIN
                IF @got <> @want
                BEGIN
                    PRINT ''FAIL t_app_schema '' + @table + ''.'' + @col + '' type is '' + @got + '', dictionary says '' + @want;
                    SET @mismatch += 1;
                END
                IF @gn <> @wn
                BEGIN
                    PRINT ''FAIL t_app_schema '' + @table + ''.'' + @col + '' is '' + CASE WHEN @gn = 1 THEN ''NULL'' ELSE ''NOT NULL'' END + '', dictionary says '' + CASE WHEN @wn = 1 THEN ''yes (may be empty)'' ELSE ''no (required)'' END;
                    SET @mismatch += 1;
                END
                IF @gi <> @wi
                BEGIN
                    PRINT ''FAIL t_app_schema '' + @table + ''.'' + @col + '' identity is '' + CAST(@gi AS varchar(1)) + '', dictionary says '' + CAST(@wi AS varchar(1));
                    SET @mismatch += 1;
                END
            END
            FETCH NEXT FROM col_cursor INTO @col, @want, @wn, @wi, @got, @gn, @gi, @have;
        END
        CLOSE col_cursor;
        DEALLOCATE col_cursor;

        -- extra columns
        SET @detail = NULL;
        SELECT @detail = ISNULL(@detail + N'', '', N'''') + a.column_name
        FROM #actual a
        WHERE a.table_name = @table
          AND NOT EXISTS (SELECT 1 FROM #expected e WHERE e.table_name = a.table_name AND e.column_name = a.column_name);
        IF @detail IS NOT NULL
        BEGIN
            PRINT ''FAIL t_app_schema '' + @table + '' has columns the dictionary does not list: '' + @detail;
            SET @mismatch += 1;
        END

        IF @mismatch = 0
        BEGIN
            -- PRINT accepts only plain values, so the count goes into a variable first
            SET @col_count = (SELECT COUNT(*) FROM #expected WHERE table_name = @table);
            PRINT ''OK  t_app_schema '' + @table + '': '' + CAST(@col_count AS varchar(10)) + '' columns match'';
        END
        ELSE
            SET @failed += 1;
    END

    FETCH NEXT FROM table_cursor INTO @table;
END
CLOSE table_cursor;
DEALLOCATE table_cursor;

DROP TABLE #actual;
DROP TABLE #expected;

IF @failed = 0
    PRINT ''t_app_schema RESULT: ALL '' + CAST(@tables AS varchar(10)) + '' TABLES MATCH THE DATA DICTIONARY'';
ELSE
    PRINT ''t_app_schema RESULT: '' + CAST(@failed AS varchar(10)) + '' OF '' + CAST(@tables AS varchar(10)) + '' TABLE(S) DIFFER FROM THE DATA DICTIONARY'';
');

PRINT N'--- db/tests/t_security_seed.sql';
EXEC (N'/* =====================================================================
   t_security_seed.sql        APP-1 test: the REF-46 security and routing seed
   Database   : the ATLAS Fabric SQL database (item of type SQL database)
   Run after  : migration 0003_security.sql and seeds 0101-0105.
   Re-runnable: yes (it only reads).

   What it checks: the counts the seed files are expected to produce, and the
   rules the client file states (who may publish, who may approve at which
   stage, which profit centres each regional group covers).

   The people loaded by db/seed/local/pov_members.sql do not change any count
   here: assignments are counted for GROUP rows only, and group members are
   not counted.

   Expected numbers come from the generator''s own summary (tools/gen_ref46_seed.py):
   16 roles, 19 groups, 13 routes, 100 route-class rows, 12 group assignments
   (3 ALL_ORCM + 9 PROFIT_CENTER_LIST), 30 scope rows, 1 alias.
   Last line: t_security_seed RESULT: ...
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL t_security_seed.0 wrong editor: connected to "'' + DB_NAME() + ''" on engine '' + ISNULL(CAST(SERVERPROPERTY(''EngineEdition'') AS varchar(20)), ''?'') + '' (11 = the warehouse-style engine, which the SQL analytics endpoint uses). Open the item named ATLAS_SQL_DB whose type is SQL database and run this from New query there.'';
    RETURN;
END

IF OBJECT_ID(N''app.role'', N''U'') IS NULL OR OBJECT_ID(N''app.role_alias'', N''U'') IS NULL
   OR OBJECT_ID(N''app.security_group'', N''U'') IS NULL OR OBJECT_ID(N''app.principal_role_assignment'', N''U'') IS NULL
   OR OBJECT_ID(N''app.principal_role_assignment_scope'', N''U'') IS NULL OR OBJECT_ID(N''app.approval_route'', N''U'') IS NULL
   OR OBJECT_ID(N''app.approval_route_class'', N''U'') IS NULL
BEGIN
    PRINT ''FAIL t_security_seed.1 a security table is missing: run migration 0003_security.sql and seeds 0101-0105 first.'';
    RETURN;
END

BEGIN TRY
    DECLARE @c TABLE
    (
        seq      int IDENTITY(1,1) NOT NULL,
        name     nvarchar(200)     NOT NULL,
        expected int               NOT NULL,
        actual   int               NOT NULL
    );

    INSERT INTO @c (name, expected, actual) VALUES
    /* roles [REF-46:L0191-L0207] */
    (N''16 roles loaded'',                                  16, (SELECT COUNT(*) FROM app.role)),
    (N''all 16 roles active'',                              16, (SELECT COUNT(*) FROM app.role WHERE is_active = 1)),
    (N''every role can view and submit requests'',           0, (SELECT COUNT(*) FROM app.role WHERE can_view = 0 OR can_submit_requests = 0)),
    (N''exactly 2 roles can publish rules'',                 2, (SELECT COUNT(*) FROM app.role WHERE can_publish_business_rules = 1)),
    (N''Admin and SAPBusinessSupport are the 2 publishers'', 2, (SELECT COUNT(*) FROM app.role WHERE can_publish_business_rules = 1 AND role_name IN (N''Admin'', N''SAPBusinessSupport''))),
    (N''9 roles approve at both stages'',                    9, (SELECT COUNT(*) FROM app.role WHERE can_responsible_approve = 1 AND can_accountable_approve = 1)),
    (N''SCM approves only as responsible'',                  1, (SELECT COUNT(*) FROM app.role WHERE role_name = N''SCM'' AND can_responsible_approve = 1 AND can_accountable_approve = 0)),
    (N''exactly 1 role can manage the admin screen'',        1, (SELECT COUNT(*) FROM app.role WHERE can_manage_admin = 1)),
    (N''that role is Admin'',                                1, (SELECT COUNT(*) FROM app.role WHERE can_manage_admin = 1 AND role_name = N''Admin'')),
    /* groups [REF-46:L0284-L0303] */
    (N''19 groups loaded'',                                 19, (SELECT COUNT(*) FROM app.security_group)),
    /* routes [REF-46:L0210-L0223] */
    (N''13 routes loaded'',                                 13, (SELECT COUNT(*) FROM app.approval_route)),
    (N''100 route-class rows (4 x 8 PSV + 4 x 17 pump)'',  100, (SELECT COUNT(*) FROM app.approval_route_class)),
    (N''8 routes with a class list'',                        8, (SELECT COUNT(*) FROM app.approval_route WHERE class_scope = N''LIST'')),
    (N''5 routes for any class'',                            5, (SELECT COUNT(*) FROM app.approval_route WHERE class_scope = N''ANY'')),
    (N''1 field-specific route (OEM_BSFC)'',                 1, (SELECT COUNT(*) FROM app.approval_route WHERE field_or_characteristic <> N''*'')),
    (N''every LIST route has classes'',                      0, (SELECT COUNT(*) FROM app.approval_route AS rt WHERE rt.class_scope = N''LIST'' AND NOT EXISTS (SELECT 1 FROM app.approval_route_class AS c WHERE c.route_id = rt.route_id))),
    (N''no ANY route has classes'',                          0, (SELECT COUNT(*) FROM app.approval_route_class AS c JOIN app.approval_route AS rt ON rt.route_id = c.route_id WHERE rt.class_scope = N''ANY'')),
    /* group assignments [REF-46:L0231-L0245] */
    (N''12 GROUP assignments'',                             12, (SELECT COUNT(*) FROM app.principal_role_assignment WHERE principal_type = N''GROUP'')),
    (N''3 GROUP assignments for all of ORCM'',               3, (SELECT COUNT(*) FROM app.principal_role_assignment WHERE principal_type = N''GROUP'' AND scope_type = N''ALL_ORCM'')),
    (N''9 GROUP assignments with a profit-centre list'',     9, (SELECT COUNT(*) FROM app.principal_role_assignment WHERE principal_type = N''GROUP'' AND scope_type = N''PROFIT_CENTER_LIST'')),
    (N''30 scope rows on GROUP assignments'',               30, (SELECT COUNT(*) FROM app.principal_role_assignment_scope AS s JOIN app.principal_role_assignment AS a ON a.assignment_id = s.assignment_id WHERE a.principal_type = N''GROUP'')),
    (N''ALL_ORCM assignments have no scope rows'',           0, (SELECT COUNT(*) FROM app.principal_role_assignment_scope AS s JOIN app.principal_role_assignment AS a ON a.assignment_id = s.assignment_id WHERE a.scope_type = N''ALL_ORCM'')),
    (N''no scope row outside the ten profit centres'',       0, (SELECT COUNT(*) FROM app.principal_role_assignment_scope AS s WHERE s.profit_center_name NOT IN (N''ROCKIES-DJ BASIN'', N''ROCKIES-PRB'', N''ROCKIES-OTHER'', N''OP RES DB TX'', N''OP RES DB NM'', N''OP RES MB'', N''OP RES MB CROWNROCK'', N''OP EOR'', N''OP EOR GAS PLANT'', N''OP EOR CO2 OPS''))),
    (N''every assignment role exists in app.role'',          0, (SELECT COUNT(*) FROM app.principal_role_assignment AS a WHERE NOT EXISTS (SELECT 1 FROM app.role AS r WHERE r.role_name = a.role_name))),
    /* the four Operations-IOC regional groups must cover each profit centre once */
    (N''4 Operations-IOC regional group assignments'',       4, (SELECT COUNT(*) FROM app.principal_role_assignment WHERE principal_type = N''GROUP'' AND role_name = N''Operations-IOC'')),
    (N''the 4 regional group keys exist as groups'',         4, (SELECT COUNT(*) FROM app.principal_role_assignment AS a JOIN app.security_group AS g ON g.group_key = a.principal_key WHERE a.principal_type = N''GROUP'' AND a.role_name = N''Operations-IOC'')),
    (N''Operations-IOC regions hold 10 scope rows'',        10, (SELECT COUNT(*) FROM app.principal_role_assignment_scope AS s JOIN app.principal_role_assignment AS a ON a.assignment_id = s.assignment_id WHERE a.principal_type = N''GROUP'' AND a.role_name = N''Operations-IOC'')),
    (N''Operations-IOC regions hold 10 different centres'', 10, (SELECT COUNT(DISTINCT s.profit_center_name) FROM app.principal_role_assignment_scope AS s JOIN app.principal_role_assignment AS a ON a.assignment_id = s.assignment_id WHERE a.principal_type = N''GROUP'' AND a.role_name = N''Operations-IOC'')),
    (N''all ten profit centres are covered by Operations-IOC'', 10,
        (SELECT COUNT(*) FROM (VALUES (N''ROCKIES-DJ BASIN''), (N''ROCKIES-PRB''), (N''ROCKIES-OTHER''), (N''OP RES DB TX''), (N''OP RES DB NM''),
                                      (N''OP RES MB''), (N''OP RES MB CROWNROCK''), (N''OP EOR''), (N''OP EOR GAS PLANT''), (N''OP EOR CO2 OPS'')) AS pc(n)
         WHERE EXISTS (SELECT 1 FROM app.principal_role_assignment_scope AS s JOIN app.principal_role_assignment AS a ON a.assignment_id = s.assignment_id
                       WHERE a.principal_type = N''GROUP'' AND a.role_name = N''Operations-IOC'' AND s.profit_center_name = pc.n))),
    /* aliases [REF-46:L0211-L0214], working assumption WA-02 / Q-496 */
    (N''exactly 1 alias'',                                   1, (SELECT COUNT(*) FROM app.role_alias)),
    (N''alias Operations-IOC - NMD -> Operations-IOC, flagged as assumption'', 1,
        (SELECT COUNT(*) FROM app.role_alias WHERE alias_name = N''Operations-IOC - NMD'' AND role_name = N''Operations-IOC'' AND is_assumption = 1 AND related_question = N''Q-496'')),
    (N''every route role exists after alias resolution'',    0,
        (SELECT COUNT(*) FROM app.approval_route AS rt
         WHERE NOT EXISTS (SELECT 1 FROM app.role AS r WHERE r.role_name = COALESCE((SELECT a.role_name FROM app.role_alias AS a WHERE a.alias_name = rt.responsible_role), rt.responsible_role))
            OR NOT EXISTS (SELECT 1 FROM app.role AS r WHERE r.role_name = COALESCE((SELECT a.role_name FROM app.role_alias AS a WHERE a.alias_name = rt.accountable_role), rt.accountable_role))));

    DECLARE @name nvarchar(200), @expected int, @actual int, @fail int = 0, @total int = 0;
    DECLARE c CURSOR LOCAL FAST_FORWARD FOR SELECT name, expected, actual FROM @c ORDER BY seq;
    OPEN c;
    FETCH NEXT FROM c INTO @name, @expected, @actual;
    WHILE @@FETCH_STATUS = 0
    BEGIN
        SET @total += 1;
        IF @expected = @actual
            PRINT ''PASS '' + @name + '' ('' + CAST(@actual AS varchar(12)) + '')'';
        ELSE
        BEGIN
            SET @fail += 1;
            PRINT ''FAIL '' + @name + '': expected '' + CAST(@expected AS varchar(12)) + '', found '' + CAST(@actual AS varchar(12));
        END
        FETCH NEXT FROM c INTO @name, @expected, @actual;
    END
    CLOSE c;
    DEALLOCATE c;

    IF @fail = 0
        PRINT ''t_security_seed RESULT: ALL '' + CAST(@total AS varchar(12)) + '' CHECKS PASS'';
    ELSE
        PRINT ''t_security_seed RESULT: '' + CAST(@fail AS varchar(12)) + '' OF '' + CAST(@total AS varchar(12)) + '' CHECK(S) FAILED'';
END TRY
BEGIN CATCH
    PRINT ''FAIL t_security_seed.9 error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' on line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE();
    PRINT ''t_security_seed RESULT: DID NOT FINISH'';
END CATCH;
');

PRINT N'--- db/tests/t_identity_resolve.sql';
EXEC (N'/* =====================================================================
   t_identity_resolve.sql    APP-1 test: id in the token -> e-mail -> what the person may do
   Covers app.usp_identity_resolve (FINAL PLAN/01 section 6.8) and
   app.usp_principal_profile, plus the constraints of app.principal_identity.
   Needs : migrations 0001-0007, seeds 0101-0105, procs usp_identity_resolve and
           usp_principal_profile. Needs no local seed.
   Safe  : everything is inserted INSIDE a transaction that is ALWAYS rolled back;
           the test people are obviously fake (@example.test, id 0000...a1). The last
           check proves nothing was left behind.
   Final line: `t_identity_resolve RESULT: ...`
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL t_identity_resolve wrong editor: connected to "'' + DB_NAME() + ''". Open the item named ATLAS_SQL_DB whose type is SQL database. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.usp_identity_resolve'', N''P'') IS NULL OR OBJECT_ID(N''app.usp_principal_profile'', N''P'') IS NULL
BEGIN
    PRINT ''FAIL t_identity_resolve a procedure is missing: run the procs and views stage first. Nothing was run.'';
    RETURN;
END
IF (SELECT COUNT(*) FROM app.role) < 16 OR (SELECT COUNT(*) FROM app.principal_role_assignment WHERE principal_type = N''GROUP'') = 0
BEGIN
    PRINT ''FAIL t_identity_resolve roles or assignments are not loaded: run seeds 0101-0105 first. Nothing was run.'';
    RETURN;
END
IF EXISTS (SELECT 1 FROM app.principal_identity WHERE user_email LIKE N''%@example.test'')
BEGIN
    PRINT ''FAIL t_identity_resolve a leftover @example.test row exists from an earlier run; delete it first. Nothing was run.'';
    RETURN;
END

DECLARE @checks int = 0, @fails int = 0;

CREATE TABLE #who (user_email nvarchar(256) NOT NULL, display_name nvarchar(100) NULL);
CREATE TABLE #p
(
    user_email nvarchar(256) NOT NULL, display_name nvarchar(100) NULL, is_registered bit NOT NULL,
    role_name nvarchar(64) NOT NULL, granted_via nvarchar(10) NOT NULL, group_key nvarchar(64) NULL,
    scope_type nvarchar(20) NOT NULL, profit_center_name nvarchar(40) NULL,
    can_view bit NOT NULL, can_submit_requests bit NOT NULL, can_request_edit_business_rules bit NOT NULL,
    can_publish_business_rules bit NOT NULL, can_request_edit_evidence_guidance bit NOT NULL,
    can_publish_evidence_guidance bit NOT NULL, can_responsible_approve bit NOT NULL,
    can_accountable_approve bit NOT NULL, can_manage_admin bit NOT NULL
);

DECLARE @id_on  nvarchar(64) = N''00000000-0000-4000-8000-0000000000a1'';
DECLARE @id_off nvarchar(64) = N''00000000-0000-4000-8000-0000000000a2'';
DECLARE @mail   nvarchar(256) = N''test.person@example.test'';
DECLARE @mail_off nvarchar(256) = N''test.off@example.test'';
DECLARE @n int, @n2 int, @err int;

BEGIN TRY
    BEGIN TRANSACTION;

    INSERT INTO app.principal_identity (external_id, user_email, display_name, is_active, bound_by, note) VALUES
        (@id_on,  @mail,     N''Test Person (synthetic)'', 1, N''test:t_identity_resolve'', NULL),
        (@id_off, @mail_off, N''Test Off (synthetic)'',    0, N''test:t_identity_resolve'', N''inactive on purpose'');

    INSERT INTO app.group_membership (group_key, user_email, is_active, added_by) VALUES
        (N''Operations-IOC-Carlsbad'', @mail, 1, N''test:t_identity_resolve''),
        (N''SAPBusinessSupport'',      @mail, 1, N''test:t_identity_resolve'');

    INSERT INTO app.principal_role_assignment (principal_type, principal_key, principal_display_name, role_name, scope_type, scope_value, is_active) VALUES
        (N''USER'', @mail, N''Test Person (synthetic)'', N''DataQualityOwner'', N''ALL_ORCM'', NULL, 1);

    /* ---- usp_identity_resolve ------------------------------------------- */
    SET @checks += 1;
    DELETE FROM #who; INSERT INTO #who EXEC app.usp_identity_resolve @external_id = @id_on;
    IF (SELECT COUNT(*) FROM #who) = 1 AND (SELECT user_email FROM #who) = @mail AND (SELECT display_name FROM #who) = N''Test Person (synthetic)''
        PRINT ''OK  resolve: an active id returns its e-mail and display name'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL resolve: an active id did not return exactly its e-mail and display name''; END

    SET @checks += 1;
    DELETE FROM #who; INSERT INTO #who EXEC app.usp_identity_resolve @external_id = N''  00000000-0000-4000-8000-0000000000A1  '';
    IF (SELECT COUNT(*) FROM #who) = 1 PRINT ''OK  resolve: capital letters and outer spaces in the id are ignored'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL resolve: an id in capitals / with spaces was not found''; END

    SET @checks += 1;
    DELETE FROM #who; INSERT INTO #who EXEC app.usp_identity_resolve @external_id = @id_off;
    IF (SELECT COUNT(*) FROM #who) = 0 PRINT ''OK  resolve: an inactive id returns no row (the function answers NOT_REGISTERED)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL resolve: an inactive id returned a row''; END

    SET @checks += 1;
    DELETE FROM #who; INSERT INTO #who EXEC app.usp_identity_resolve @external_id = N''00000000-0000-4000-8000-0000000000ff'';
    SELECT @n = COUNT(*) FROM #who;
    DELETE FROM #who; INSERT INTO #who EXEC app.usp_identity_resolve @external_id = N'''';
    SELECT @n2 = COUNT(*) FROM #who;
    DELETE FROM #who; INSERT INTO #who EXEC app.usp_identity_resolve @external_id = NULL;
    IF @n = 0 AND @n2 = 0 AND (SELECT COUNT(*) FROM #who) = 0 PRINT ''OK  resolve: an unknown, an empty and a NULL id return no row'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL resolve: an unknown, empty or NULL id returned a row''; END

    /* ---- constraints of app.principal_identity ---------------------------- */
    SET @checks += 1;
    SET @err = NULL;
    BEGIN TRY
        INSERT INTO app.principal_identity (external_id, user_email, display_name, is_active, bound_by)
        VALUES (N''00000000-0000-4000-8000-0000000000B1'', N''upper.id@example.test'', N''x'', 1, N''test:t_identity_resolve'');
    END TRY
    BEGIN CATCH
        SET @err = ERROR_NUMBER();
    END CATCH;
    IF @err = 547 PRINT ''OK  constraint: an upper-case id is refused (error 547)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL constraint: an upper-case external_id was accepted or failed differently (error '' + ISNULL(CAST(@err AS varchar(12)), ''none'') + '')''; END

    SET @checks += 1;
    SET @err = NULL;
    BEGIN TRY
        INSERT INTO app.principal_identity (external_id, user_email, display_name, is_active, bound_by)
        VALUES (N''00000000-0000-4000-8000-0000000000b2'', N''Mixed.Case@example.test'', N''x'', 1, N''test:t_identity_resolve'');
    END TRY
    BEGIN CATCH
        SET @err = ERROR_NUMBER();
    END CATCH;
    IF @err = 547 PRINT ''OK  constraint: an e-mail that is not lower case is refused (error 547)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL constraint: a mixed-case e-mail was accepted or failed differently (error '' + ISNULL(CAST(@err AS varchar(12)), ''none'') + '')''; END

    SET @checks += 1;
    SET @err = NULL;
    BEGIN TRY
        INSERT INTO app.principal_identity (external_id, user_email, display_name, is_active, bound_by)
        VALUES (@id_on, N''second.person@example.test'', N''x'', 1, N''test:t_identity_resolve'');
    END TRY
    BEGIN CATCH
        SET @err = ERROR_NUMBER();
    END CATCH;
    IF @err IN (2627, 2601) PRINT ''OK  constraint: the same id cannot be bound twice (error '' + CAST(@err AS varchar(12)) + '')'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL constraint: a duplicate external_id was accepted or failed differently (error '' + ISNULL(CAST(@err AS varchar(12)), ''none'') + '')''; END

    /* ---- usp_principal_profile ---------------------------------------------- */
    DELETE FROM #p; INSERT INTO #p EXEC app.usp_principal_profile @email = @mail;

    SET @checks += 1;
    SELECT @n = COUNT(*), @n2 = SUM(CAST(is_registered AS int)) FROM #p;
    IF @n > 0 AND @n2 = @n AND (SELECT COUNT(DISTINCT user_email) FROM #p) = 1 AND (SELECT MIN(user_email) FROM #p) = @mail
        PRINT ''OK  profile: the person is registered and every row carries the e-mail ('' + CAST(@n AS varchar(10)) + '' rows)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL profile: expected rows for a registered person, got '' + CAST(@n AS varchar(10)) + '' (registered on '' + ISNULL(CAST(@n2 AS varchar(10)), ''0'') + '')''; END

    SET @checks += 1;
    SELECT @n = COUNT(*), @n2 = COUNT(DISTINCT profit_center_name) FROM #p WHERE role_name = N''Operations-IOC'' AND granted_via = N''GROUP'' AND group_key = N''Operations-IOC-Carlsbad'';
    IF @n = 1 AND @n2 = 1 AND EXISTS (SELECT 1 FROM #p WHERE role_name = N''Operations-IOC'' AND profit_center_name = N''OP RES DB NM'')
        PRINT ''OK  profile: Operations-IOC through the Carlsbad group is limited to OP RES DB NM'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL profile: Operations-IOC via Operations-IOC-Carlsbad should be exactly the profit centre OP RES DB NM (rows '' + CAST(@n AS varchar(10)) + '')''; END

    SET @checks += 1;
    SELECT @n = COUNT(DISTINCT profit_center_name) FROM #p WHERE role_name = N''SAPBusinessSupport'' AND granted_via = N''GROUP'' AND group_key = N''SAPBusinessSupport'';
    IF @n = 10 PRINT ''OK  profile: SAPBusinessSupport covers all ten profit centres (the client''''s two scope rows together)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL profile: SAPBusinessSupport should cover 10 profit centres, found '' + CAST(@n AS varchar(10)); END

    SET @checks += 1;
    IF EXISTS (SELECT 1 FROM #p WHERE role_name = N''DataQualityOwner'' AND granted_via = N''USER'' AND scope_type = N''ALL_ORCM'' AND profit_center_name IS NULL)
        PRINT ''OK  profile: a USER assignment (DataQualityOwner, ALL_ORCM) is returned with no profit-centre row'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL profile: the direct DataQualityOwner assignment is missing''; END

    SET @checks += 1;
    IF EXISTS (SELECT 1 FROM #p WHERE role_name = N''GeneralViewer'' AND granted_via = N''IMPLICIT'')
        PRINT ''OK  profile: a registered person is an implicit GeneralViewer'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL profile: no implicit GeneralViewer row for a registered person''; END

    SET @checks += 1;
    IF (SELECT MAX(CAST(can_view AS int)) FROM #p) = 1
       AND (SELECT MAX(CAST(can_submit_requests AS int)) FROM #p) = 1
       AND (SELECT MAX(CAST(can_request_edit_business_rules AS int)) FROM #p) = 1
       AND (SELECT MAX(CAST(can_publish_business_rules AS int)) FROM #p) = 1
       AND (SELECT MAX(CAST(can_responsible_approve AS int)) FROM #p) = 1
       AND (SELECT MAX(CAST(can_accountable_approve AS int)) FROM #p) = 1
       AND (SELECT MAX(CAST(can_manage_admin AS int)) FROM #p) = 0
        PRINT ''OK  profile: flags combine as expected (view, submit, edit and publish rules, both approvals on; admin off)'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL profile: the combined flags are not what DataQualityOwner + SAPBusinessSupport + Operations-IOC + GeneralViewer should give''; END

    SET @checks += 1;
    DELETE FROM #p; INSERT INTO #p EXEC app.usp_principal_profile @email = N''nobody.at.all@example.test'';
    SELECT @n = COUNT(*) FROM #p;
    DELETE FROM #p; INSERT INTO #p EXEC app.usp_principal_profile @email = @mail_off;
    SELECT @n2 = COUNT(*) FROM #p;
    IF @n = 0 AND @n2 = 0 PRINT ''OK  profile: an unknown e-mail and an inactive identity get no rows'';
    ELSE BEGIN SET @fails += 1; PRINT ''FAIL profile: unknown e-mail gave '' + CAST(@n AS varchar(10)) + '' row(s), inactive identity '' + CAST(@n2 AS varchar(10)); END

    ROLLBACK TRANSACTION;
END TRY
BEGIN CATCH
    IF @@TRANCOUNT > 0 ROLLBACK TRANSACTION;
    SET @fails += 1;
    PRINT ''FAIL t_identity_resolve stopped on error '' + CAST(ERROR_NUMBER() AS varchar(12)) + '' at line '' + CAST(ERROR_LINE() AS varchar(12)) + '': '' + ERROR_MESSAGE() + '' (the transaction was rolled back)'';
END CATCH;

/* ---- nothing left behind ---------------------------------------------------- */
SET @checks += 1;
SELECT @n = (SELECT COUNT(*) FROM app.principal_identity WHERE user_email LIKE N''%@example.test'')
          + (SELECT COUNT(*) FROM app.group_membership WHERE user_email LIKE N''%@example.test'')
          + (SELECT COUNT(*) FROM app.principal_role_assignment WHERE principal_key LIKE N''%@example.test'');
IF @n = 0 PRINT ''OK  cleanup: the test rows were rolled back, nothing is left'';
ELSE BEGIN SET @fails += 1; PRINT ''FAIL cleanup: '' + CAST(@n AS varchar(10)) + '' @example.test row(s) were left behind; delete them by hand''; END

DROP TABLE #p;
DROP TABLE #who;

IF @fails = 0 PRINT ''t_identity_resolve RESULT: ALL '' + CAST(@checks AS varchar(10)) + '' CHECKS PASS'';
ELSE PRINT ''t_identity_resolve RESULT: '' + CAST(@fails AS varchar(10)) + '' OF '' + CAST(@checks AS varchar(10)) + '' CHECK(S) FAILED'';
');

PRINT N'--- db/tests/t_route_resolve.sql';
EXEC (N'/* =====================================================================
   t_route_resolve.sql       APP-1 test: who approves what (app.usp_route_resolve)
   Needs : migrations 0001-0007, seeds 0101-0105, procs fn_group_for_role,
           usp_route_resolve, views vw_route_check and vw_group_member_count.
   Reads only. Needs no local seed (no people) and leaves nothing behind.
   Final line: `t_route_resolve RESULT: ...`

   Cases: one per Operations-IOC region (all ten profit centres), a PSV class, a
   pump class, the OEM_BSFC field route, precedence (field beats class), FLOC routes,
   the alias "Operations-IOC - NMD", no route at all, and an unknown profit centre.
   Expected groups follow REF-46 [REF-46:L0211-L0223, L0235-L0245].
   ===================================================================== */
SET NOCOUNT ON;

IF CAST(SERVERPROPERTY(''EngineEdition'') AS int) = 11
   OR @@VERSION LIKE N''%Data Warehouse%''
   OR DB_NAME() NOT LIKE N''ATLAS[_]SQL[_]DB%''
BEGIN
    PRINT ''FAIL t_route_resolve wrong editor: connected to "'' + DB_NAME() + ''". Open the item named ATLAS_SQL_DB whose type is SQL database. Nothing was run.'';
    RETURN;
END
IF OBJECT_ID(N''app.usp_route_resolve'', N''P'') IS NULL OR OBJECT_ID(N''app.fn_group_for_role'') IS NULL
   OR OBJECT_ID(N''app.vw_route_check'', N''V'') IS NULL OR OBJECT_ID(N''app.vw_group_member_count'', N''V'') IS NULL
BEGIN
    PRINT ''FAIL t_route_resolve a procedure, function or view is missing: run the procs and views stage first. Nothing was run.'';
    RETURN;
END
IF (SELECT COUNT(*) FROM app.approval_route) = 0 OR (SELECT COUNT(*) FROM app.principal_role_assignment WHERE principal_type = N''GROUP'') = 0
BEGIN
    PRINT ''FAIL t_route_resolve the routes or assignments are not loaded: run seeds 0101-0105 first. Nothing was run.'';
    RETURN;
END

DECLARE @checks int = 0, @fails int = 0;

CREATE TABLE #r
(
    route_id int NULL, route_used nvarchar(12) NOT NULL,
    responsible_role nvarchar(64) NULL, responsible_group nvarchar(64) NOT NULL,
    accountable_role nvarchar(64) NULL, accountable_group nvarchar(64) NOT NULL
);

