 (3,  N''Midland: OP RES DB TX'',                           N''EQUIPMENT'', N''UPDATE'', N''OP RES DB TX'',        N''HEAT_DUTY'',     N''HEATER'', N''WILDCARD'', NULL,             N''Operations-IOC-Midland'',    N''SAPBusinessSupport''),
